  PRIMARY KEY (`task_id`) USING BTREE,
  INDEX `idx_ai_index_task_doc`(`doc_id`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI 知识库索引任务' ROW_FORMAT = Dynamic;

