INSERT INTO `ai_knowledge_chunk` VALUES (28, 6, 3, 0, '# StarPivot 审批中心操作手册\n\n审批中心是 StarPivot 的统一审批中台，可与商城采购、退货、优惠券、商品上架等业务联动。菜单路径：左侧「审批中心」。\n\n## 审批中心子菜单\n\n| 菜单 | 路径 | 用途 |\n|------|------|------|\n| 审批模板 | 审批中心 → 审批模板 | 配置审批流程步骤、审批人策略、超时规则 |\n| 业务绑定 | 审批中心 → 业务绑定 | 将业务类型（如采购单）绑定到具体审批模板 |\n| 待办审批 | 审批中心 → 待办审批 | 处理分配给自己的待办，进行通过或驳回 |\n| 我发起的 | 审批中心 → 我发起的 | 查看自己提交的审批进度，可撤回进行中的审批 |\n| 审批统计 | 审批中心 → 审批统计 | 查看审批数据看板与统计 |\n\n## 审批状态说明\n\n### 审批实例状态\n- 审批中：流程正在进行，有待办未处理\n- 已通过：所有审批节点均已通过\n- 已驳回：某一节点审批人驳回，流程结束\n- 已撤回：发起人主动撤回，流程结束\n\n### 业务单 audit_status（以商城为例）\n- DRAFT：草稿，可编辑，可提交审批\n- PENDING：审批中，一般不可直接执行业务后续操作\n- APPROVED：审批已通过，可继续入库、上架、发布等\n- REJECTED：已驳回，需修改后重新提交', '[-0.07306917756795883, -0.04330591857433319, -0.06786634773015976, 0.011285553686320782, -0.02756352908909321, -0.030796170234680176, 0.01996969059109688, 0.06189839169383049, 0.005269779358059168, 0.03603725880384445, 0.02811824344098568, 0.03184821456670761, 0.016717921942472458, 0.05275518074631691, 0.00999440997838974, -0.03840913623571396, 0.06063593924045563, 0.009296235628426077, 0.03603725880384445, -0.005374983884394169, -0.08775952458381653, -0.006981740705668926, 0.017444787546992302, 0.01674661412835121, 0.023910069838166237, 0.037299711257219315, -0.029227670282125473, -0.01916631311178207, 0.040704503655433655, -0.026473229750990868, 0.01867854781448841, -0.09013140201568604, -0.013915660791099072, -0.03810308873653412, 0.027372248470783234, -0.06243397668004036, -0.0011590407229959965, -0.0006730685126967728, -0.06924356520175934, 0.014279094524681568, -0.05160749703645706, -0.026243694126605988, 0.019338464364409447, -0.027754809707403183, -0.005217177327722311, -0.037988319993019104, 0.026626255363225937, -0.047361068427562714, -0.04483616352081299, 0.01402086578309536, -0.03238379955291748, 0.010128306224942207, 0.012844489887356758, -0.07062078267335892, 0.02983976900577545, 0.06002384051680565, -0.0007794682751409709, -0.03351235389709473, 0.002802260220050812, 0.038007449358701706, -0