INSERT INTO `ai_knowledge_chunk` VALUES (30, 6, 3, 2, 'finance 角色的用户\n在「系统管理 → 角色管理」中为用户分配 finance 等角色后，需重新登录生效。\n\n## 业务用户：发起审批（以采购单为例）\n\n1. 进入「商城系统 → 仓库系统 → 采购单」\n2. 新建或选择 audit_status 为「草稿」的采购单，填写明细并保存\n3. 打开采购单详情，点击「提交审批」\n4. 提交成功后，业务单变为「审批中」，详情页出现审批时间线\n5. 在「审批中心 → 我发起的」可查看进度\n\n其他业务类型提交入口：\n- 退货单：商城 → 订单 → 退货单详情 → 提交审批\n- 优惠券：商城 → 优惠营销 → 优惠券 → 提交审批\n- 商品 SPU：商城 → 商品管理 → 提交审批\n\n## 审批人：处理待办\n\n1. 进入「审批中心 → 待办审批」，切换到「待办」Tab\n2. 找到待处理记录，点击「通过」或「驳回」\n3. 通过：审批意见可选填\n4. 驳回：必须填写审批意见，说明驳回原因\n5. 多级审批时，需按顺序逐关处理；当前关通过后，下一关审批人会在待办中收到任务\n6. 处理完成后可在「已办」Tab 查看历史记录\n\n若待办列表为空：当前登录用户不是该步骤的审批人，需切换有权限的账号或联系管理员调整角色。\n\n## 发起人：撤回审批', '[-0.06877358257770538, -0.029649142175912857, -0.04143501818180084, -0.005732750054448843, -0.04877449199557304, 0.010271379724144936, 0.07401606440544128, 0.052385978400707245, -0.002667354885488749, 0.03605661913752556, 0.04815315827727318, 0.026154154911637303, -0.01879526488482952, 0.057783789932727814, 0.005203648004680872, -0.03050347231328487, 0.04042535275220871, -0.03199855238199234, 0.0018542850157245991, 0.004970648791640997, -0.03491104021668434, -0.01657206565141678, 0.00902386289089918, -0.03933802619576454, 0.038541942834854126, 0.03126072138547897, -0.056851793080568314, -0.04504650458693504, 0.05312380939722061, 0.006892891600728035, 0.01564006879925728, -0.047842495143413544, -0.05370630696415901, -0.03607603535056114, 0.013009119778871536, -0.015445902943611143, 0.01878555677831173, -0.025843489915132523, -0.07999637722969055, -0.01151404157280922, -0.005907499697059393, 0.027668649330735207, 0.008994738571345806, -0.0009180409251712264, 0.002684344537556171, -0.002941614482551813, -0.011591708287596704, -0.020348593592643734, -0.007931679487228394, 0.006790954619646072, -0.03553237020969391, -0.02163008786737919, 0.03500812500715256, -0.038250695914030075, 0.00875203125178814, 0.08683101832866669, 0.03275579959154129, -0.047725994139909744, 0.012601370923221111, 0.025804657489061356, -0.02215433679521084, -0.00019492443243507296,