INSERT INTO `ai_knowledge_chunk` VALUES (33, 7, 3, 0, '# StarPivot AI 中心管理员指南\n\nAI 中心用于配置智能对话助手、管理知识库（RAG）、查看会话与用量。菜单路径：左侧「AI 中心」。普通用户通过页面右下角 AI 图标打开对话窗口。\n\n## AI 中心子菜单\n\n| 菜单 | 用途 |\n|------|------|\n| 基础配置 | 助手名称、欢迎语、系统提示词、模型、RAG 开关等 |\n| 会话管理 | 管理员查看与删除用户对话会话 |\n| 知识库 | 维护 RAG 文档，上传产品手册、FAQ 等 |\n| 用量统计 | 查看 AI 调用次数、Token 消耗、耗时等 |\n\n## 开启 RAG 知识库问答（必做两步）\n\nRAG 需要同时满足两个开关，缺一不可：\n\n### 开关一：Nacos 基础设施（运维配置）\n在 Nacos 的 starpivot-ai.yaml 中设置：\n- starpivot.ai.rag.enabled: true\n- spring.ai.openai.embedding 配置 DashScope 等 Embedding API\n- embedding 的 base-url 不要带 /v1（Spring AI 会自动追加）\n\n修改后需重启 starpivot-ai 服务。', '[-0.031870000064373016, -0.02816373854875565, -0.061037518084049225, -0.0010821998585015535, -0.07725241780281067, -0.043123915791511536, 0.02515240013599396, 0.020384445786476135, -0.00726292422041297, 0.030789008364081383, -0.003346736077219248, -0.007639341522008181, -0.006543870549649, 0.046096645295619965, 0.042737845331430435, -0.03833665698766709, 0.03769964352250099, 0.0370626300573349, 0.04497704654932022, -0.02258503995835781, -0.05567115917801857, 0.014188038185238838, -0.015616493299603462, 0.01835758425295353, 0.04100053384900093, 0.05906856432557106, -0.05829642713069916, -0.04042143002152443, 0.08624783158302307, -0.02930264174938202, -0.014294207096099854, -0.09381478279829024, -0.023550212383270264, -0.003045119810849428, 0.0151918176561594, -0.024476777762174606, -0.007094019092619419, -0.0127499308437109, -0.10501078516244888, 0.0077744657173752785, -0.04389605298638344, -0.038703422993421555, 0.01728624291718006, -0.00864312145859003, 0.017855694517493248, -0.023955585435032845, -0.004459097515791655, -0.04080750048160553, 0.006288100033998489, 0.02223757840692997, -0.05003454908728599, -0.020191412419080738, -0.005076807923614979, -0.019921163097023964, 0.032043732702732086, 0.04350998252630234, -0.012643761932849884, -0.03671516850590706, -0.01468992792069912, 0.02146543934941292, -0.07350754737854004, -0.020886335521936417, -0.0094828