INSERT INTO `ai_knowledge_chunk` VALUES (34, 7, 3, 1, 'g API\n- embedding 的 base-url 不要带 /v1（Spring AI 会自动追加）\n\n修改后需重启 starpivot-ai 服务。\n\n### 开关二：后台业务开关\n1. 进入「AI 中心 → 基础配置」\n2. 编辑默认配置（或新建并设为默认）\n3. 在「RAG 知识库」区域打开「启用 RAG」\n4. 设置「检索条数」（建议 3～10，默认 5）\n5. 保存\n\n## 基础配置项说明\n\n| 配置项 | 说明 |\n|--------|------|\n| 配置名称 | 如 default，用于区分多套配置 |\n| 助手名称 | 对话窗口显示的名称，支持欢迎语 {botName} 占位符 |\n| 助手头像 | 完整图片 URL，留空用默认头像 |\n| 欢迎语 | 打开新会话时展示的首条消息 |\n| 系统提示词 | 定义 AI 行为边界与回答风格 |\n| 默认模型 | 如 deepseek-chat，需与 Nacos 中配置的模型一致 |\n| 默认温度 | 0～2，越低越稳定，越高越有创造性 |\n| 记忆条数 | 每个会话保留的历史消息条数，默认 30 |\n| 启用 RAG | 是否在本配置下启用知识库检索 |\n| 检索条数 | 每次对话从知识库检索的片段数量 |\n| 设为默认 | 同时只能有一套默认配置生效 |\n\n## 对话场景（提示词模板）', '[-0.04448398202657699, -0.03205578401684761, -0.047176435589790344, 0.0163107942789793, -0.06340918689966202, -0.07058905810117722, 0.06949646770954132, 0.017813103273510933, -0.03640662878751755, 0.007643246091902256, -0.009491867385804651, 0.026163605973124504, 0.020251918584108353, 0.02657332643866539, 0.026514794677495956, -0.04448398202657699, 0.051546793431043625, 0.028446337208151817, 0.027529342100024223, -0.017744816839694977, -0.03732362389564514, 0.01877887547016144, -0.013472013175487518, -0.012662326917052267, 0.0566585473716259, 0.0605996735394001, -0.0767543837428093, -0.036055438220500946, 0.05802428349852562, -0.01039910688996315, -0.005545865278691053, -0.03882593289017677, 0.00021217689209152013, -0.04350845888257027, 0.00796029157936573, -0.01788139156997204, -0.02056408673524857, 0.0020742120686918497, -0.1158144399523735, 0.003980145789682865, -0.029363330453634266, -0.020271429792046547, 0.015910828486084938, -0.014271944761276243, 0.013803692534565926, -0.037030965089797974, 0.005848278291523457, -0.04998594895005226, 0.03792845085263252, 0.0032875225879251957, -0.04292314127087593, -0.0003350322076585144, -0.003921614494174719, -0.015393799170851707, 0.0326215885579586, 0.03098270483314991, -0.01545233093202114, 0.01835939846932888, -0.040933068841695786, -0.009238230995833874, -