INSERT INTO `ai_knowledge_chunk` VALUES (35, 7, 3, 2, '下启用知识库检索 |\n| 检索条数 | 每次对话从知识库检索的片段数量 |\n| 设为默认 | 同时只能有一套默认配置生效 |\n\n## 对话场景（提示词模板）\n\n用户可在对话窗口切换场景，不同场景使用不同系统提示词：\n\n| 场景 ID | 名称 | 适用场景 |\n|---------|------|----------|\n| default | 通用助手 | 日常问答、写作、翻译 |\n| support | 客服问答 | 产品使用、操作指引、FAQ（推荐配合 RAG） |\n| developer | 开发辅助 | 编程、调试、架构（默认使用 deepseek-reasoner） |\n| analyst | 数据分析 | 报表解读、指标分析 |\n\n维护产品 FAQ 后，建议用户选择「客服问答」场景提问。\n\n## 知识库管理\n\n### 新建知识库\n1. 「AI 中心 → 知识库」→ 新增知识库\n2. 填写名称、描述\n3. 可调整：检索条数、分块大小（默认 600 字）、分块重叠（默认 80 字）\n\n### 添加文档\n进入知识库 → 文档管理，两种方式：\n- 上传文件：支持 PDF、DOCX、MD、TXT，单文件不超过 20MB\n- 粘贴文本：直接粘贴标题和正文', '[-0.05694985389709473, -0.0330512560904026, -0.01942005753517151, 0.01483395043760538, -0.060352765023708344, -0.0731038972735405, 0.008531722240149975, 0.04803188145160675, -0.02382037229835987, 0.0031657821964472532, 0.0031877837609499693, -0.012604458257555962, 0.005823083687573671, 0.06966187804937363, 0.03604346886277199, -0.0402873270213604, -0.011890629306435583, 0.01965473964810371, 0.00689871609210968, -0.034107331186532974, -0.028944294899702072, 0.03768625482916832, 0.04936175420880318, 0.042712390422821045, 0.07106997817754745, 0.07384706288576126, -0.07599832862615585, -0.05573732405900955, 0.06363832950592041, -0.0505351722240448, 0.00985181611031294, -0.0607830174267292, -0.016476735472679138, 0.002439730102196336, 0.021610435098409653, -0.03248410299420357, -0.01477527990937233, -0.009049980901181698, -0.0856594666838646, 0.0006612695869989693, -0.0028259800747036934, -0.03162359818816185, 0.04897061735391617, -0.008517053909599781, 0.011587495915591717, -0.023155435919761658, 0.013582305982708933, -0.027360180392861366, 0.058357954025268555, -0.02608897909522057, -0.03946593776345253, -0.02696904167532921, 0.029707014560699463, -0.03224942088127136, -0.028514040634036064, 0.038977012038230896, -0.06379479169845581, -0.02370302937924862, -0.04584150388836861, -0.013298729434609411, -0.07013124227523804, -0.01067809760570526, 0.00209992821328