INSERT INTO `ai_knowledge_chunk` VALUES (36, 7, 3, 3, '添加文档\n进入知识库 → 文档管理，两种方式：\n- 上传文件：支持 PDF、DOCX、MD、TXT，单文件不超过 20MB\n- 粘贴文本：直接粘贴标题和正文\n\n### 索引状态\n| 状态 | 含义 | 处理 |\n|------|------|------|\n| 待索引 | 任务已创建，等待处理 | 稍等刷新 |\n| 索引中 | 正在分块与生成向量 | 稍等，勿重复提交 |\n| 已完成 | 可用于 RAG 检索 | 正常 |\n| 失败 | 索引出错 | 查看错误信息，点「重建索引」 |\n\n文档内容更新后，须点击「重建索引」才会更新向量。\n\n### 文档编写建议\n- 标题具体，如「用户登录与密码重置」\n- FAQ 采用「问：… 答：…」格式，一段一问一答\n- 避免纯图片 PDF（无法提取文字）\n- 用用户会搜索的关键词描述功能\n\n## 会话管理\n\n路径：「AI 中心 → 会话管理」\n- 可查看所有用户的 AI 对话会话列表\n- 可查看某会话的消息历史\n- 可删除违规或测试会话\n需权限：ai:session:query、ai:session:delete\n\n## 用量统计\n\n路径：「AI 中心 → 用量统计」\n查看 AI 调用日志：模型、请求类型（同步/流式）、Token 数、耗时、是否成功。\n用于成本监控与异常排查。\n\n## 限流说明', '[-0.08580581843852997, -0.005854378454387188, -0.011874216608703136, 0.024877456948161125, -0.052402280271053314, -0.029646610841155052, 0.017422007396817207, 0.047886185348033905, -0.0034406029153615236, -0.026532061398029327, 0.0038299215957522392, 0.005737582687288523, 0.027583222836256027, 0.04399299994111061, 0.03624556213617325, -0.010638130828738213, -0.008535809814929962, 0.0060539040714502335, -0.006190165411680937, -0.030308451503515244, -0.020770147442817688, 0.02818666584789753, 0.06022758409380913, 0.05547789856791496, 0.0436815470457077, 0.044810570776462555, -0.041734952479600906, -0.05318091809749603, 0.07323082536458969, -0.08650659024715424, 0.0300943274050951, -0.04340902343392372, 0.038192152976989746, 0.010861988179385662, -0.005873844027519226, -0.019232338294386864, -0.023748433217406273, -0.018181178718805313, -0.0736980065703392, 0.030250053852796555, -0.005250934511423111, -0.056022945791482925, 0.015631141141057014, -0.03507760539650917, -0.01711055263876915, 0.012224603444337845, -0.015533811412751676, -0.012312199920415878, -0.003250810317695141, -0.027232835069298744, -0.03920438140630722, -0.0056840511970222, 0.028361858800053596, -0.035233333706855774, 0.02569502592086792, 0.05586721748113632, -0.03867880254983902, -0.020302964374423027, -0.06252456456422806, -0.01320763304829597