INSERT INTO `ai_knowledge_chunk` VALUES (37, 7, 3, 4, 'AI 中心 → 用量统计」\n查看 AI 调用日志：模型、请求类型（同步/流式）、Token 数、耗时、是否成功。\n用于成本监控与异常排查。\n\n## 限流说明\n\n默认每用户每分钟最多 30 次对话请求（发送 + 流式合计），可在 Nacos 配置：\nstarpivot.ai.rate-limit.enabled 与 max-requests-per-minute\n超限提示：「对话请求过于频繁，请稍后再试」\n\n## RAG 高级配置（Nacos，运维）\n\n| 配置项 | 说明 | 建议 |\n|--------|------|------|\n| hyde-enabled | HyDE 查询增强，用假设性回答改善检索 | 可开启 |\n| reranker.enabled | 精排模型二次排序 | 可开启，需 DashScope rerank API |\n| min-vector-score | 向量相似度阈值 | 默认 0.3，召回少时可降到 0.1 测试 |\n| retrieve-top-k | 精排前候选池大小 | 默认 10～20 |\n\n## 权限配置\n\n为用户开通 AI 功能，在「系统管理 → 角色管理」中勾选：\n- AI 中心菜单及子菜单\n- 按钮权限：ai:config:edit、ai:knowledge:edit、ai:session:query 等', '[-0.004798667971044779, -0.04170040041208267, -0.04378163442015648, -0.0016768139321357012, -0.09793160855770112, -0.0431005023419857, 0.03044280596077442, 0.012459035031497478, -0.05331747978925705, 0.0384461022913456, -0.033299773931503296, -0.01550520770251751, 0.0279831625521183, 0.028607534244656563, 0.06137754023075104, -0.026772262528538704, 0.033186253160238266, 0.008849983103573322, 0.000981491873972118, -0.03600538149476051, -0.029364345595240593, 0.05460406094789505, -0.023120637983083725, 0.03636486828327179, 0.019866343587636948, 0.09112029522657394, -0.07772470265626907, -0.02208002097904682, 0.11344628036022186, 0.03273216634988785, 0.03617566451430321, -0.05097135901451111, 0.04665752500295639, -0.02484238892793655, 0.002691416535526514, -0.015334924682974815, -0.023442285135388374, -0.011058930307626724, -0.10073181986808775, 0.03958132117986679, 0.001504165935330093, -0.01068998407572508, 0.0068160477094352245, -0.007421498186886311, 0.034264709800481796, -0.01629040017724037, 0.00035268670762889087, -0.042949140071868896, 0.0000813721853774041, 0.016299860551953316, -0.015249783173203468, -0.03133206069469452, -0.014360527507960796, -0.012269831262528896, -0.0009968647500500083, 0.06769692897796631, -0.0013303353916853666, -0.030196839943528175, -0.013319909572601318, 0.019128449261188507, -