INSERT INTO `ai_knowledge_chunk` VALUES (39, 8, 3, 0, '# StarPivot 商城仓储操作手册\n\n商城仓储模块用于管理仓库、商品库存、采购与出入库作业。菜单路径：左侧「商城系统 → 仓库系统」。\n\n## 子模块一览\n\n| 菜单 | 路径 | 用途 |\n|------|------|------|\n| 仓库维护 | 商城 → 仓库系统 → 仓库维护 | 维护仓库基础信息（名称、地址、负责人等） |\n| 地区管理 | 商城 → 仓库系统 → 地区管理 | 维护省市区等地区数据 |\n| 商品库存 | 商城 → 仓库系统 → 商品库存 | 查看各仓库 SKU 库存数量 |\n| 库存工作单 | 商城 → 仓库系统 → 库存工作单 | 处理订单出库、拣货、发货等仓储作业 |\n| 采购需求 | 商城 → 仓库系统 → 采购单维护 → 采购需求 | 登记需采购的商品明细 |\n| 采购单 | 商城 → 仓库系统 → 采购单维护 → 采购单 | 汇总采购需求、提交审批、领取与完成采购 |\n\n## 仓库维护\n\n1. 进入「仓库维护」，点击新增\n2. 填写仓库名称、地址、负责人、联系方式等信息\n3. 保存后可在「商品库存」中选择该仓库查看库存\n\n权限标识：mall:ware:query（查询）、mall:ware:add（新增）、mall:ware:edit（修改）、mall:ware:delete（删除）\n\n## 商品库存', '[-0.044436004012823105, -0.030372781679034233, -0.1076733022928238, 0.022840935736894608, -0.02050021104514599, -0.05345911532640457, 0.026219883933663368, 0.04749404639005661, -0.019858401268720627, -0.0038414301816374063, 0.028032056987285617, 0.014506826177239418, -0.0477583184838295, 0.0523265078663826, 0.03246810659766197, -0.017697006464004517, 0.02187821827828884, 0.04235955327749252, 0.008126465603709221, -0.060745563358068466, -0.04636143520474434, -0.04832462593913078, 0.005412924103438854, 0.07007070630788803, 0.010155721567571163, 0.006517217494547367, -0.018999505788087845, -0.020519088953733444, 0.037130679935216904, -0.03918825089931488, -0.009065586142241957, -0.024690862745046616, -0.014705032110214232, 0.002351342234760523, -0.010155721567571163, -0.019669631496071815, 0.035545025020837784, 0.021897096186876297, -0.07161860167980194, 0.025936732068657875, -0.07105229794979095, -0.032298214733600616, 0.01899006776511669, 0.0032420915085822344, 0.00560641149058938, -0.013695122674107552, -0.009929200634360312, -0.04016984254121781, -0.04749404639005661, -0.027427999302744865, -0.022746551781892776, -0.01139215286821127, 0.00025365708279423416, -0.04485129192471504, 0.08358649909496307, 0.0520244799554348, 0.00023817220062483105, -0.06323730200529099, -0.021651696413755417, 0.0021684730891138315, -0