INSERT INTO `ai_knowledge_chunk` VALUES (41, 8, 3, 2, '「已通过」\n2. 业务状态为「新建」或「已分配」时可领取\n3. 在采购单列表勾选记录，点击「领取采购单」\n4. 领取后状态变为「已领取」，采购人开始执行采购\n\n### 第五步：完成采购\n1. 采购执行完毕后，在详情中完成采购操作\n2. 状态变为「已完成」，库存相应增加\n\n## 采购单状态说明\n\n### 审批状态（audit_status）\n- 草稿：可编辑，可提交审批\n- 审批中：等待审批人处理\n- 已通过：可领取并执行采购\n- 已驳回：需修改后重新提交审批\n- 已撤回：发起人撤回，可修改后再次提交\n\n### 业务状态（status）\n- 新建：刚创建，未分配\n- 已分配：已指定采购人\n- 已领取：采购人已领取，执行中\n- 已完成：采购完成\n- 有异常：执行过程出现异常，需处理\n\n## 库存工作单\n\n库存工作单关联订单出库流程，用于仓库拣货、打包、发货。\n1. 进入「库存工作单」列表\n2. 可按订单号、物流单号、仓库、状态筛选\n3. 打开详情处理对应作业步骤\n4. 完成后订单进入发货状态\n\n## 与审批中心联动\n\n以下仓储/商城业务支持提交审批：\n- 采购单（purchase）\n- 退货单（return）— 在订单模块\n- 优惠券（coupon）— 在营销模块\n- 商品 SPU（spu）— 在商品模块', '[-0.014858419075608252, -0.031177079305052757, -0.05241693928837776, 0.02882552333176136, -0.030684011057019234, -0.007220603991299868, 0.012895628809928894, 0.06963639706373215, -0.04987573996186256, 0.03732146695256233, 0.026834286749362946, 0.039142027497291565, -0.0012119283201172948, 0.09785506129264832, 0.006898213177919388, -0.028029028326272964, 0.043883066624403, -0.030418511480093, -0.019703762605786324, -0.028085920959711075, -0.036411188542842865, 0.006485742516815662, 0.014924793504178524, 0.04790346696972847, 0.017816828563809395, 0.0012113357661291957, -0.04073501378297806, -0.024331016466021534, 0.03730250149965286, -0.012952521443367004, -0.005020761396735907, -0.03601294010877609, -0.05533741787075997, -0.03038058429956436, 0.002448747167363763, -0.015465272590517998, -0.00949156191200018, -0.004328569397330284, -0.0626196563243866, 0.03582329675555229, -0.044565774500370026, 0.003404066665098071, 0.013805908150970936, -0.061102524399757385, 0.03679047152400017, 0.011084550991654396, -0.018878821283578873, -0.03599397465586662, -0.03091157972812653, -0.017437545582652092, -0.03447684273123741, 0.004195820540189743, 0.04547605663537979, -0.0573476180434227, 0.06432642787694931, 0.0904969722032547, 0.014090370386838911, -0.04198664799332619, -0.02825659886002541, -0.0017921130638569591, -0.0311960428953170