INSERT INTO `ai_knowledge_chunk` VALUES (42, 8, 3, 3, '- 采购单（purchase）\n- 退货单（return）— 在订单模块\n- 优惠券（coupon）— 在营销模块\n- 商品 SPU（spu）— 在商品模块\n\n审批通过后，业务单 audit_status 变为 APPROVED，方可继续后续操作（如领取采购单、商品上架）。\n\n## 常见问题\n\n问：为什么不能提交采购审批？\n答：当前审批状态不是草稿/已驳回/已撤回，或采购单无有效明细。\n\n问：审批通过了但无法领取采购单？\n答：须同时满足：审批状态「已通过」且业务状态为「新建」或「已分配」。\n\n问：采购需求如何合并？\n答：勾选多条采购需求，点「合并到采购单」，可新建或并入已有采购单。\n\n问：库存数量不对？\n答：检查采购是否已完成入库、订单出库工作单是否已处理；查看对应业务单据状态。\n\n问：看不到仓库系统菜单？\n答：联系管理员在角色管理中分配商城仓储相关菜单权限。', '[-0.06207597255706787, -0.01277866866439581, -0.033759281039237976, 0.0218274500221014, -0.044378042221069336, -0.03455854207277298, 0.027098769322037697, 0.06005879119038582, -0.01676546037197113, 0.03151373565196991, 0.04704224690794945, 0.03973471373319626, 0.02239835076034069, 0.07516863942146301, 0.0033706948161125183, -0.03621415421366691, 0.05507291853427887, -0.043388478457927704, -0.00916296150535345, -0.002557160798460245, -0.04289369657635689, 0.01708897203207016, 0.02413008362054825, 0.004900233820080757, 0.02175132930278778, 0.024358443915843964, -0.0687364861369133, -0.015214513055980206, 0.021047217771410946, -0.012141162529587746, -0.007754738908261061, -0.041333235800266266, -0.015832988545298576, -0.051038552075624466, 0.003603812772780657, -0.026623018085956573, -0.006389334332197905, -0.013406659476459026, -0.05294155701994896, 0.023844633251428604, -0.047803446650505066, -0.0011037420481443403, 0.002114712493494153, -0.0655013769865036, 0.03619512543082237, -0.0055853151716291904, -0.000028507884053396992, -0.027555489912629128, -0.03377830982208252, 0.010209613479673862, -0.03366412967443466, -0.016289709135890007, 0.05914534628391266, -0.06401703506708145, 0.04350265860557556, 0.06633870303630829, 0.0328839011490345, 0.015128877945244312, -0.009990768507122992, 0.03067641519010067, -0.03726080805063248, -0.005885038059204817, 0.02413008362054825, 0.01676546037197113, -0.02924916334450245, 0.02472001500427723, 0.014938577078282831, -0.04220861569046974, -0.011084995232522488, -0.04201831