INSERT INTO `ai_knowledge_chunk` VALUES (43, 9, 3, 0, '# StarPivot 消息中心使用说明\n\n消息中心是 StarPivot 全平台统一站内信收件箱，用于接收审批通知、业务告警、系统群发等消息。支持顶栏铃铛实时提醒与消息列表管理。\n\n## 入口\n\n### 顶栏铃铛（快捷入口）\n- 登录后页面右上角铃铛图标\n- 显示未读消息角标\n- 点击可预览最近 10 条消息\n- 点击「查看全部」进入完整消息中心\n\n### 消息中心页面\n路径：「系统管理 → 消息中心」\n路由：/system/message/index\n\n## 消息类型\n\n| 类型 | 说明 | 来源 |\n|------|------|------|\n| 审批待办 | 有新的审批任务分配给你 | 审批中心 |\n| 审批结果 | 你发起的审批通过/驳回/撤回 | 审批中心 |\n| 订单消息 | 订单相关业务通知 | 商城订单 |\n| 退款告警 | 退款失败等异常告警 | 商城订单（通知 finance、admin 角色） |\n| 系统通知 | 一般系统级通知 | 各业务模块 |\n| 系统群发 | 管理员手动群发的公告 | 消息中心「群发消息」 |\n\n## 普通用户：查看与已读\n\n1. 进入「系统管理 → 消息中心」，或点击顶栏铃铛\n2. 列表中未读消息行会高亮显示\n3. 可按「已读状态」「消息类型」筛选\n4. 点击某条消息行：自动标记为已读，并跳转到关联业务页（如采购单、待办审批）', '[-0.06593918055295944, -0.00956741627305746, -0.06835538893938065, -0.009621001780033112, -0.013649644330143929, -0.06067807599902153, -0.0004822679329663515, 0.02815665304660797, -0.01080475002527237, 0.0004235067463014275, 0.02141464501619339, 0.020148083567619324, -0.0004682626749854535, 0.03127434477210045, 0.002014321042224765, -0.05124705657362938, 0.07533122599124908, 0.018676921725273132, 0.02714340388774872, -0.024454394355416294, -0.0754091665148735, 0.046375665813684464, -0.007311961147934198, 0.06332810968160629, 0.01997271180152893, 0.06044424697756767, -0.040763817727565765, -0.04462196305394173, 0.04294620454311371, -0.021882299333810806, 0.04415430873632431, -0.05759935453534126, 0.020226025953888893, 0.014994148164987564, -0.016465310007333755, -0.01978760026395321, 0.005636202171444893, 0.0039360858500003815, -0.07490254193544388, -0.0030275708995759487, -0.05405297875404358, -0.02114184759557247, 0.001448021619580686, -0.02398674003779888, -0.009124119766056538, -0.046063896268606186, 0.0252727884799242, -0.03906857594847679, 0.01311379112303257, 0.005621587857604027, -0.04127044230699539, 0.009840214625000954, 0.02402571216225624, -0.04988306760787964, 0.03131331503391266, 0.02293452061712742, 0.008958492428064346, -0.034431006759405136, -0.013863985426723955, 0.004274