INSERT INTO `ai_knowledge_chunk` VALUES (44, 9, 3, 1, '铃铛\n2. 列表中未读消息行会高亮显示\n3. 可按「已读状态」「消息类型」筛选\n4. 点击某条消息行：自动标记为已读，并跳转到关联业务页（如采购单、待办审批）\n5. 点击「全部已读」一键清空未读角标\n\n### 消息跳转规则\n- 审批待办 → 审批中心待办审批\n- 审批结果 → 审批中心我发起的\n- 采购单相关 → 商城采购单详情\n- 退货单 → 订单退货单\n- 优惠券 → 营销优惠券\n- 商品 → 商品管理\n\n## 管理员：群发消息\n\n需权限：system:message:send（「消息群发」按钮权限）\n超级管理员和 admin 角色默认可用。\n\n操作步骤：\n1. 进入「系统管理 → 消息中心」\n2. 点击「群发消息」\n3. 填写标题、正文\n4. 选择接收用户（可多人）\n5. 发送后，目标用户收件箱和顶栏铃铛会收到「系统群发」类型消息\n\n## 实时推送说明\n\n- 新消息落库后通过 SSE 长连接推送到浏览器\n- 顶栏铃铛未读数会自动更新，无需手动刷新页面\n- 若长时间收不到实时推送：尝试重新登录；检查 starpivot-system 服务与 Redis 是否正常\n\n## 权限配置\n\n| 权限标识 | 说明 |\n|----------|------|\n| system:message:list | 进入消息中心菜单 |', '[-0.0835995227098465, 0.04342574626207352, -0.028633233159780502, -0.015347730368375778, -0.01325575914233923, -0.04346540570259094, 0.023775100708007812, 0.03355085104703903, -0.026808954775333405, 0.00931472424417734, 0.00815472099930048, 0.025242455303668976, -0.0077581387013196945, 0.04513105005025864, 0.057068176567554474, -0.04168078675866127, 0.08907235413789749, -0.031468793749809265, 0.01892688497900963, -0.027066733688116074, -0.031548112630844116, 0.05413346737623215, -0.03491906076669693, 0.03834949806332588, 0.05861484631896019, 0.06499981880187988, -0.054847314953804016, -0.038686592131853104, 0.034026749432086945, -0.029565200209617615, 0.037833940237760544, -0.02641237340867519, 0.011619857512414455, 0.014584309421479702, -0.0371597483754158, 0.008025831542909145, 0.0049300119280815125, -0.025242455303668976, -0.0694415420293808, -0.01079694926738739, -0.03977719321846962, 0.0400547981262207, 0.034304358065128326, -0.04715362191200256, -0.006151981186121702, -0.0007342966855503619, 0.012482424266636372, -0.02258535474538803, 0.03511735051870346, -0.003579154144972563, -0.06262032687664032, 0.00944857019931078, 0.03192486613988876, -0.039340950548648834, 0.027661606669425964, 0.03593034669756889, 0.0299221258610487, -0.02060244418680668, -0.022347405552864075, -0.003415564075112343, -0.03795291483402