INSERT INTO `ai_knowledge_chunk` VALUES (45, 9, 3, 2, '## 权限配置\n\n| 权限标识 | 说明 |\n|----------|------|\n| system:message:list | 进入消息中心菜单 |\n| system:message:query | 查询消息列表 |\n| system:message:edit | 标记已读、全部已读 |\n| system:message:send | 群发消息 |\n\n在「系统管理 → 角色管理」中为角色勾选「消息中心」及对应按钮权限，用户重新登录后生效。\n\n## 与其他模块的关系\n\n### 审批中心\n- 待办分配时发送「审批待办」消息\n- 审批完结时向发起人发送「审批结果」消息\n\n### 商城订单\n- 退款失败等异常向 finance、admin 角色发送「退款告警」\n\n### 历史数据迁移\n若从旧版审批通知升级，需执行 sql/patch_migrate_ap_notification_to_sys_user_message.sql 迁移历史通知，并重启相关服务。\n\n## 部署与初始化（管理员）\n\n首次启用消息中心需执行：\nsql/patch_sys_user_message.sql\n然后重启 starpivot-system、starpivot-approval、starpivot-mall-order 及网关，用户重新登录。\n\n## 常见问题', '[-0.03865428268909454, -0.011411034502089024, -0.06306148320436478, 0.021217839792370796, -0.04805048182606697, -0.07184654474258423, 0.05404724180698395, 0.020912272855639458, 0.011449230834841728, -0.014438061974942684, 0.04048768803477287, 0.03727922961115837, -0.0018799559911713004, 0.03107239119708538, -0.008842358365654945, -0.02688993513584137, 0.08380187302827835, 0.010112373158335686, 0.027119111269712448, 0.007873136550188065, -0.05725570023059845, -0.010647116228938104, 0.008049792610108852, 0.034567318856716156, 0.02329951897263527, 0.05928008630871773, -0.03714554384350777, -0.03930361196398735, 0.04690460488200188, -0.013750535435974598, 0.01209856104105711, -0.06252674013376236, 0.023433204740285873, 0.008336261846125126, -0.002635519253090024, -0.023643281310796738, -0.0014848668361082673, -0.007281099446117878, -0.0893784761428833, -0.004232586827129126, -0.04319959878921509, -0.03145435079932213, 0.010331999510526655, -0.010847644880414007, 0.012576010078191755, -0.04648444801568985, -0.008183478377759457, -0.048470638692379, -0.007328844163566828, 0.01553619559854269, -0.04636986181139946, -0.01305346004664898, 0.006092251278460026, -0.020587606355547905, 0.088996522128582, 0.05125894024968147, 0.01073305681347847, 0.01715952157974243, 0.007920881733298302, 0.02786393277347088, -0.0535506978631