INSERT INTO `ai_knowledge_chunk` VALUES (46, 9, 3, 3, 'starpivot-system、starpivot-approval、starpivot-mall-order 及网关，用户重新登录。\n\n## 常见问题\n\n问：顶栏铃铛没有未读角标，但消息中心有消息？\n答：刷新页面或重新登录，重建 SSE 连接；检查浏览器是否拦截长连接。\n\n问：点击消息没有跳转？\n答：部分旧消息可能缺少业务关联字段；可手动进入对应业务模块查找。\n\n问：收不到审批通知？\n答：确认你是当前步骤的审批人；检查审批服务是否运行；查看消息中心是否已有记录（可能仅推送延迟）。\n\n问：普通用户能否群发消息？\n答：不能，须具备 system:message:send 权限，一般为管理员。\n\n问：消息能删除吗？\n答：当前以已读管理为主，消息记录保留在收件箱供查阅；具体清理策略由系统维护。', '[-0.08499476313591003, 0.013931456953287125, -0.04637878015637398, -0.015594914555549622, -0.0037972379941493273, -0.05184442922472954, 0.030377903953194615, 0.042695410549640656, -0.015278065577149391, -0.003829417983070016, 0.04554705321788788, 0.022793328389525417, 0.013357168063521383, 0.029169917106628414, 0.02897188626229763, -0.036556459963321686, 0.10701577365398408, -0.016674181446433067, 0.01092139072716236, -0.013367069885134695, -0.054973311722278595, 0.05703283101320267, 0.004633917473256588, 0.007842014543712139, 0.04014081507921219, 0.06507287919521332, -0.04214092344045639, -0.05069584771990776, 0.03659606724977493, -0.02570438012480736, 0.034496940672397614, -0.0395665280520916, 0.03909125179052353, -0.019199073314666748, -0.003589305793866515, -0.013475986197590828, 0.002184525830671191, -0.02073381096124649, -0.073469378054142, -0.009406456723809242, -0.06471642106771469, 0.02120908349752426, 0.0110996188595891, -0.060478564351797104, 0.011891741305589676, -0.04249738156795502, 0.008733152411878109, -0.02948676608502865, 0.014139389619231224, 0.013297758996486664, -0.033071119338274, 0.016228612512350082, 0.016307825222611427, -0.04083392396569252, 0.05378512665629387, 0.023684468120336533, 0.058181408792734146, 0.01354529708623886, -0.009406456723809242, 0.00351504422724247, -0.05037900060415268, -0.008921281434595585, 0.02251608669757843, -0.03855656832456589, -0.010723360814154148, 0.09751030057668686, 0.016149399802088737, -0.009619339369237425, -0.023941906169056892, -0.0026511354371905327, -0.008886625990271568, 0.0444776862