INSERT INTO `ai_knowledge_chunk` VALUES (48, 4, 1, 0, '# StarPivot 常见问题 FAQ\n\n## 登录与账号\n\n问：忘记密码怎么办？\n答：请联系系统管理员在「系统管理 → 用户管理」中重置密码。若环境已对接自助找回流程，可在登录页使用忘记密码功能（以实际部署为准）。\n\n问：登录后左侧菜单很少，很多功能看不到？\n答：这是权限未分配导致。请管理员进入「系统管理 → 角色管理」，编辑你的角色，勾选需要的菜单和按钮权限后保存，然后退出重新登录。\n\n问：提示无权限或 403？\n答：说明当前账号缺少该功能的按钮权限（如 ai:knowledge:edit）。需管理员在角色管理中补充对应权限标识。\n\n问：登录后很快掉线？\n答：Token 可能过期或被踢下线。可在「系统监控 → 在线用户」查看会话；重新登录即可。若频繁掉线，联系管理员检查 Redis 与 JWT 配置。\n\n## 用户与权限管理\n\n问：如何新增一个后台用户？\n答：进入「系统管理 → 用户管理」，点击新增，填写用户名、昵称、部门、岗位，分配角色后保存。\n\n问：如何给用户开通 AI 知识库管理权限？\n答：在「系统管理 → 角色管理」中，为角色勾选「AI 中心」及其子菜单（基础配置、知识库、会话管理等），并勾选对应按钮权限（如 ai:knowledge:edit）。', '[-0.036800988018512726, -0.03270561248064041, -0.06678910553455353, -0.0027151014655828476, -0.0671718493103981, -0.036533065140247345, 0.07677876204252243, 0.014525195583701134, 0.016247550025582314, -0.031251177191734314, 0.045240528881549835, -0.008463461883366108, -0.03128945082426071, 0.028667645528912544, 0.035958949476480484, -0.04585292190313339, 0.05021622031927109, 0.05756493657827377, -0.01020973827689886, -0.01150150503963232, -0.034676749259233475, -0.0010232464410364628, -0.0038609460461884737, 0.03812146186828613, 0.03888695314526558, 0.07042519003152847, -0.020955320447683334, -0.04191064089536667, 0.06908557564020157, -0.034657612442970276, 0.03458106517791748, -0.08359163999557495, -0.018630141392350197, -0.047958023846149445, -0.01844833791255951, -0.02660081908106804, 0.007678833324462175, 0.015261980704963207, -0.07693186402320862, 0.014228567481040956, -0.027232348918914795, -0.03877212852239609, 0.009286364540457726, -0.03517432138323784, -0.005492398981004953, -0.0357484370470047, 0.022773362696170807, 0.0012463153107091784, 0.028112662956118584, -0.012046917341649532, -0.007884559221565723, 0.014965352602303028, 0.026524269953370094, -0.08351508527994156, 0.018649278208613396, 0.03278215974569321, 0.007913265377283096, -0.027959564700722694, -0.005568948108702898, 0.02085963450372219, -0.04914453253149986, 0.006779381074011326, -0.03