INSERT INTO `ai_knowledge_chunk` VALUES (49, 4, 1, 1, '统管理 → 角色管理」中，为角色勾选「AI 中心」及其子菜单（基础配置、知识库、会话管理等），并勾选对应按钮权限（如 ai:knowledge:edit）。\n\n问：超级管理员和普通管理员有什么区别？\n答：超级管理员通常拥有全部菜单权限；普通角色仅拥有被分配的菜单与按钮权限，遵循最小权限原则。\n\n## 审批中心\n\n问：如何发起审批？\n答：进入「审批中心」，选择对应业务类型的审批模板或入口，填写表单后提交。可在「我发起的」查看进度。\n\n问：审批被驳回了怎么办？\n答：在「我发起的」或待办列表中打开该单据，查看驳回意见，修改内容后重新提交。\n\n问：收不到审批通知？\n答：检查「系统管理 → 消息中心」是否有站内消息；确认审批服务与消息服务正常运行，必要时重新登录刷新消息连接。\n\n## 商城相关\n\n问：商品上架后 C 端看不到？\n答：检查商品审核/上架状态、库存是否充足，以及 C 端商城入口是否正常。B 端在「商城系统 → 商品管理」维护。\n\n问：订单支付失败？\n答：开发环境可能使用支付沙箱，检查支付配置与订单状态；生产环境联系运维确认支付渠道配置。\n\n## 文件中心\n\n问：上传文件失败？\n答：检查文件大小是否超限、当前用户是否有 file:resource 相关权限，以及文件服务（starpivot-file）与 OSS/存储配置是否正常。\n\n## AI 助手与知识库', '[-0.05952718108892441, -0.04981160536408424, -0.036896057426929474, -0.006491508800536394, -0.03548884019255638, -0.03514185547828674, 0.03340693190693855, 0.030881652608513832, 0.001710828160867095, 0.003939724061638117, 0.037493642419576645, -0.019778138026595116, 0.007161382120102644, 0.06315124779939651, 0.013243256136775017, -0.005614407826215029, 0.03760930523276329, 0.006852951366454363, -0.014409510418772696, -0.015045649372041224, -0.07356078922748566, 0.0018722724635154009, -0.022476907819509503, 0.02195643074810505, 0.05420674756169319, 0.05771515145897865, -0.0636138916015625, -0.057753704488277435, 0.047536928206682205, -0.001272277906537056, 0.00559513084590435, -0.09630757570266724, -0.004248154815286398, -0.04553212597966194, 0.012607117183506489, -0.02563832700252533, -0.014390233904123306, -0.016703465953469276, -0.08119446039199829, 0.01695406623184681, -0.02311304770410061, -0.018688989803195, 0.019575729966163635, -0.04634175822138786, 0.0015445646131411197, -0.01050593052059412, 0.02662144973874092, -0.047344159334897995, -0.003469848772510886, 0.022207031026482586, -0.04745981842279434, -0.004751765169203281, 0.0011433633044362068, -0.020915476605296135, 0.025349171832203865, 0.09677022695541382, 0.04468394070863724, -0.005556577350944281, 0.0032023810781538486, 0.0741391032934188