INSERT INTO `ai_knowledge_chunk` VALUES (50, 4, 1, 2, '当前用户是否有 file:resource 相关权限，以及文件服务（starpivot-file）与 OSS/存储配置是否正常。\n\n## AI 助手与知识库\n\n问：AI 助手在哪里打开？\n答：登录管理端后，点击页面右下角的 AI 对话图标即可打开聊天窗口。\n\n问：AI 能回答公司内部产品问题吗？\n答：可以，需同时满足：① Nacos 中 RAG 已开启；②「AI 中心 → 基础配置」中启用 RAG；③ 知识库中已上传文档且索引状态为「已完成」。否则 AI 仅按通用知识回答。\n\n问：如何在知识库添加文档？\n答：进入「AI 中心 → 知识库」，选择知识库后进入文档管理，可「上传文件」（支持 PDF、DOCX、MD、TXT）或「粘贴文本」。保存后等待索引完成。\n\n问：知识库文档索引一直失败？\n答：常见原因：Embedding API 未配置或地址错误（DashScope 的 base-url 不要带 /v1）、文档为纯图片 PDF 无法解析。可在文档列表点击「重建索引」，并查看后台 IndexService 日志。\n\n问：AI 回答没有引用知识库内容？\n答：确认提问用语与文档内容相关；检查日志是否有 vectorHits > 0；知识库文档是否索引完成且 RAG 双开关均已开启。', '[-0.05274525657296181, -0.03368637338280678, -0.016480442136526108, -0.0042794244363904, -0.04850994795560837, -0.04603935405611992, 0.025215761736035347, 0.045294251292943954, -0.03441186621785164, 0.0017879955703392625, 0.021098101511597633, -0.030039304867386814, 0.025666743516921997, 0.03521579131484032, 0.04329424723982811, -0.0077696312218904495, -0.014882397837936878, 0.002110300352796912, -0.01995103992521763, -0.03168636932969093, -0.03347068652510643, 0.029843226075172424, 0.04423542693257332, 0.0252353698015213, 0.08274534344673157, 0.06898059695959091, -0.03909815475344658, -0.03396088629961014, 0.08925516903400421, -0.0558825209736824, 0.006750020198523998, -0.07690218836069107, 0.00501227006316185, -0.0087892422452569, 0.013843178749084473, -0.03831383958458901, -0.005838252604007721, -0.025941254571080208, -0.07152962684631348, 0.01613730378448963, -0.04580405727028847, -0.017686327919363976, 0.030804013833403587, -0.0572158582508564, -0.03347068652510643, -0.008549044840037823, -0.005730409175157547, -0.018166720867156982, 0.0231961477547884, 0.013284353539347649, -0.02131378836929798, -0.020960846915841103, 0.013392196968197824, -0.03360794484615326, 0.01295101922005415, 0.033862847834825516, -0.006191194988787174, -0.02002947218716145, -0.07239237427711487, 0.004007365088909864, -0.05415702611207962, -0.03809815272688866, -0.05160799622535