INSERT INTO `ai_knowledge_chunk` VALUES (51, 4, 1, 3, '回答没有引用知识库内容？\n答：确认提问用语与文档内容相关；检查日志是否有 vectorHits > 0；知识库文档是否索引完成且 RAG 双开关均已开启。\n\n问：AI 对话可以选择不同场景吗？\n答：可以。系统支持多种提示词场景（如通用助手、客服问答、开发辅助、数据分析），在对话窗口切换场景后，回答风格会相应调整。\n\n## 系统运维（开发环境参考）\n\n问：服务启动后接口 502 或连不上？\n答：检查网关（8080）、对应微服务是否已注册到 Nacos（8848），以及 MySQL（3307）、Redis（6379）是否已启动。常用命令：docker compose up -d 启动中间件。\n\n问：修改 Nacos 配置后不生效？\n答：部分配置支持热刷新，AI Embedding 等客户端通常需重启对应微服务（如 starpivot-ai）后生效。\n\n问：数据库脚本在哪里？\n答：项目 sql/ 目录，核心库为 star_pivot；商城等业务有独立分库脚本，详见项目 README。', '[-0.024380235001444817, -0.02801052108407021, -0.04688800871372223, 0.024934330955147743, -0.07302606850862503, -0.048187267035245895, 0.061829499900341034, 0.04830190911889076, -0.02801052108407021, 0.018743738532066345, 0.004592789337038994, -0.007341775577515364, 0.02992119826376438, 0.024246487766504288, 0.020272281020879745, -0.025392893701791763, 0.011196565814316273, 0.020998338237404823, 0.03842370957136154, -0.0308001097291708, -0.04065920040011406, 0.013947940431535244, 0.043945565819740295, 0.039245299994945526, 0.04524482414126396, 0.08261766284704208, -0.08208267390727997, -0.06010989099740982, 0.09484599530696868, -0.011024604551494122, -0.0029949857853353024, -0.06171485781669617, 0.002340578939765692, -0.03700980916619301, 0.010489615611732006, -0.03806068003177643, 0.006424650549888611, 0.010566042736172676, -0.09186533838510512, 0.034621462225914, -0.017234304919838905, -0.029195141047239304, 0.023864353075623512, -0.00377358659170568, 0.034984491765499115, -0.040429919958114624, -0.012620019726455212, -0.03739194571971893, 0.009887752123177052, 0.0009744451381266116, -0.0573585145175457, -0.01886793226003647, 0.006730359047651291, -0.04188203439116478, 0.0026701707392930984, 0.0021710065193474293, -0.01735849864780903, -0.04994508996605873, -0.05961311608552933, 0.04979223757982254, -0.060797736048698425, 0.033933620899915695, 0.02071173675358295, -0.0013303087325766685, -0.015438267961144447, 0.05598282814025879, -0.029844770208001137, 0