-- ----------------------------
-- Table structure for sys_file_ref
-- ----------------------------
DROP TABLE IF EXISTS `sys_file_ref`;
CREATE TABLE `sys_file_ref`  (
  `ref_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '引用ID',
  `file_id` bigint(0) NOT NULL COMMENT '文件ID',
  `biz_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `biz_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务主键',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间',
  PRIMARY KEY (`ref_id`) USING BTREE,
  UNIQUE INDEX `uk_file_biz`(`file_id`, `biz_type`, `biz_id`) USING BTREE,
  INDEX `idx_file_id`(`file_id`) USING BTREE,
  INDEX `idx_biz`(`biz_type`, `biz_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '文件业务引用计数' ROW_FORMAT = Dynamic;

